function validate([colors, queries]) {
  if (!Array.isArray(colors) || colors.length < 1 || colors.length > 50000) return 'colors needs 1 to 50,000 values.';
  if (colors.some(v => v !== 1 && v !== 2 && v !== 3)) return 'Each color is 1, 2 or 3.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 50,000 pairs.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [i, c].';
    const [i, c] = query;
    if (!Number.isInteger(i) || i < 0 || i >= colors.length) return 'Each query index must be a valid index of colors.';
    if (c !== 1 && c !== 2 && c !== 3) return 'Each query color is 1, 2 or 3.';
  }
  return null;
}

