function shortestDistanceColor(colors, queries) {
  const positions = [[], [], [], []];
  for (let i = 0; i < colors.length; i++) {
    positions[colors[i]].push(i);
  }

  const result = [];
  for (const [index, color] of queries) {
    const list = positions[color];
    if (list.length === 0) {
      result.push(-1);
      continue;
    }
    let left = 0;
    let right = list.length - 1;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (list[mid] < index) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    let best = Math.abs(list[left] - index);
    if (left > 0) {
      best = Math.min(best, index - list[left - 1]);
    }
    result.push(best);
  }
  return result;
}

