function shortestDistanceColor(colors, queries) {
  return queries.map(([i, c]) => {
    let best = -1;
    for (let j = 0; j < colors.length; j++) {
      if (colors[j] !== c) continue;
      const d = Math.abs(i - j);
      if (best === -1 || d < best) best = d;
    }
    return best;
  });
}

