function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const q = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  // Sometimes leave a color out entirely so that -1 answers appear.
  const palette = [1, 2, 3].filter(() => rand() < 0.75);
  if (palette.length === 0) palette.push(1 + Math.floor(rand() * 3));
  const colors = Array.from({ length: n }, () => palette[Math.floor(rand() * palette.length)]);
  const queries = Array.from({ length: q }, () => [Math.floor(rand() * n), 1 + Math.floor(rand() * 3)]);
  return [colors, queries];
}
